/**
 * Products API
 * 
 * Manages product profiles - the core entity that drives all marketing decisions.
 * Each product has its own marketing strategy generated by AI.
 */

import { NextResponse } from "next/server"
import { auth } from "@clerk/nextjs/server"
import { prisma } from "@/lib/db"
import { generateMarketingStrategy } from "@/lib/strategy"

// GET /api/products - Get all products for user
export async function GET() {
  try {
    const { userId: clerkId } = await auth()
    if (!clerkId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const user = await prisma.user.findUnique({
      where: { clerkId },
      include: {
        products: {
          include: {
            strategy: true,
          },
          orderBy: { createdAt: "desc" },
        },
      },
    })

    if (!user) {
      return NextResponse.json({ products: [] })
    }

    return NextResponse.json({ 
      products: user.products,
      activeProductId: user.activeProductId,
    })
  } catch (error) {
    console.error("Error fetching products:", error)
    return NextResponse.json(
      { error: "Failed to fetch products" },
      { status: 500 }
    )
  }
}

// POST /api/products - Create a new product and generate its marketing strategy
export async function POST(request: Request) {
  try {
    const { userId: clerkId } = await auth()
    if (!clerkId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const { 
      name, 
      type, 
      industry, 
      audience, 
      audienceDetail,
      stage, 
      salesMotion, 
      description, 
      website, 
      competitors 
    } = body

    // Validate required fields
    if (!name || !type || !industry || !audience || !stage || !salesMotion) {
      return NextResponse.json(
        { error: "Missing required fields: name, type, industry, audience, stage, salesMotion" },
        { status: 400 }
      )
    }

    // Get or create user
    let user = await prisma.user.findUnique({ where: { clerkId } })
    if (!user) {
      user = await prisma.user.create({
        data: {
          clerkId,
          email: `${clerkId}@temp.com`, // Will be updated from Clerk
        },
      })
    }

    // Create product
    const product = await prisma.product.create({
      data: {
        userId: user.id,
        name,
        type,
        industry,
        audience,
        audienceDetail: audienceDetail || undefined,
        stage,
        salesMotion,
        description,
        website,
        competitors,
      },
    })

    // Generate marketing strategy
    const strategyOutput = await generateMarketingStrategy({
      name,
      type,
      industry,
      audience,
      audienceDetail: audienceDetail || undefined,
      stage,
      salesMotion,
      description,
      website,
      competitors,
    }, user.tier)

    // Save strategy to database
    const strategy = await prisma.marketingStrategy.create({
      data: {
        productId: product.id,
        platforms: JSON.stringify(strategyOutput.platforms),
        contentTypes: JSON.stringify(strategyOutput.contentTypes),
        tone: JSON.stringify(strategyOutput.tone),
        visualStyle: JSON.stringify(strategyOutput.visualStyle ?? { style: "diagram-only" }),
        cadence: JSON.stringify(strategyOutput.cadence),
        proofTypes: JSON.stringify(strategyOutput.proofTypes),
        antiPatterns: JSON.stringify(strategyOutput.antiPatterns),
        summary: strategyOutput.summary,
        reasoning: strategyOutput.reasoning,
        confidence: strategyOutput.confidence,
      },
    })

    // Set as active product if it's the first one
    const productCount = await prisma.product.count({ where: { userId: user.id } })
    if (productCount === 1) {
      await prisma.user.update({
        where: { id: user.id },
        data: { activeProductId: product.id },
      })
    }

    return NextResponse.json({ 
      product: {
        ...product,
        strategy,
      },
      strategyGenerated: true,
    })
  } catch (error) {
    console.error("Error creating product:", error)
    return NextResponse.json(
      { error: "Failed to create product" },
      { status: 500 }
    )
  }
}

// PATCH /api/products - Set active product
export async function PATCH(request: Request) {
  try {
    const { userId: clerkId } = await auth()
    if (!clerkId) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
    }

    const body = await request.json()
    const { activeProductId } = body

    const user = await prisma.user.findUnique({ where: { clerkId } })
    if (!user) {
      return NextResponse.json({ error: "User not found" }, { status: 404 })
    }

    // Verify product belongs to user
    if (activeProductId) {
      const product = await prisma.product.findFirst({
        where: { id: activeProductId, userId: user.id },
      })
      if (!product) {
        return NextResponse.json({ error: "Product not found" }, { status: 404 })
      }
    }

    await prisma.user.update({
      where: { id: user.id },
      data: { activeProductId },
    })

    return NextResponse.json({ success: true, activeProductId })
  } catch (error) {
    console.error("Error updating active product:", error)
    return NextResponse.json(
      { error: "Failed to update active product" },
      { status: 500 }
    )
  }
}
